"""Stream event sequencer."""
from typing import List, Dict
from sort_helper import order_packets, get_max_severity
from event_packet import EventPacket

def sequence_stream_batch(packets: List[EventPacket]) -> List[EventPacket]:
    """Sequence event packets by severity and stream_id."""
    return order_packets(packets)

def get_highest_priority_packet(packets: List[EventPacket]) -> Optional[EventPacket]:
    ordered = sequence_stream_batch(packets)
    return ordered[0] if ordered else None

def get_batch_severity_peak(packets: List[EventPacket]) -> int:
    return get_max_severity(packets)

def _tiebreaker(packets: List[EventPacket]) -> Dict[str, List[EventPacket]]:
    """Group packets by severity to apply tiebreaker logic."""
    severity_groups = {}
    for packet in packets:
        if packet.severity not in severity_groups:
            severity_groups[packet.severity] = []
        severity_groups[packet.severity].append(packet)
    return severity_groups

def apply_tiebreaker(packets: List[EventPacket]) -> List[EventPacket]:
    """Apply tiebreaker logic to resolve out-of-order streams."""
    severity_groups = _tiebreaker(packets)
    ordered_packets = []
    for severity in sorted(severity_groups.keys(), reverse=True):
        ordered_packets.extend(sorted(severity_groups[severity], key=lambda p: p.stream_id))
    return ordered_packets
